    /// <summary>
    /// Create Vendor price agreements
    /// </summary>
    /// <param name = "_vendAccount">Vendor account</param>
    /// <param name = "_inventLocationId">Invent Location</param>
    private void createVendPriceTermAgreements(VendAccount _vendAccount, InventLocationId _inventLocationId)
    {
        GUPPriceTermJournalTable        gupPriceTermJournalTable;
        GUPPriceTermJournalTransEntity  gupPriceTermJournalTransEntityMainItem, gupPriceTermJournalTransEntityTempItem, gupPriceTermJournalTransEntity;
        int countLoop = 0;

        GUPAgreementId agreementId = _vendAccount + METConstants::hyphen +_inventLocationId;

        select firstonly forupdate gupPriceTermJournalTable
            where gupPriceTermJournalTable.AgreementId == agreementId;

        if (gupPriceTermJournalTable)
        { 
            gupPriceTermJournalTable.Status = GUPDisabledEnabled::Disabled;
            gupPriceTermJournalTable.update();

            METPurchUnit metpurchUnit       = inventItemPurchSetupOrigItem.METPurchUnit;
            
            select forupdate firstonly gupPriceTermJournalTransEntityMainItem
                order by gupPriceTermJournalTransEntityMainItem.RecId desc
                where gupPriceTermJournalTransEntityMainItem.AgreementId == agreementId
                && gupPriceTermJournalTransEntityMainItem.UnitId == metpurchUnit
                && gupPriceTermJournalTransEntityMainItem.line1 == metInventItemOrderSetupOrigItem.ItemId;                            
            if (gupPriceTermJournalTransEntityMainItem)
            {
                gupPriceTermJournalTransEntityMainItem.ValidTo = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
                gupPriceTermJournalTransEntityMainItem.update();
            }

            metpurchUnit       = inventItemPurchSetupTempItem.METPurchUnit;

            RecordInsertList gupPriceTermJournalTransEntityRecordInsertList = new RecordInsertList(tableNum(GUPPriceTermJournalTransEntity));

            while select gupPriceTermJournalTransEntityTempItem
                where gupPriceTermJournalTransEntityTempItem.AgreementId == agreementId
                && gupPriceTermJournalTransEntityTempItem.UnitId == metpurchUnit
                && gupPriceTermJournalTransEntityTempItem.line1 == metInventItemOrderSetupTempItem.ItemId
                && (gupPriceTermJournalTransEntityTempItem.ValidFrom >= DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone())
                || gupPriceTermJournalTransEntityTempItem.ValidFrom >= DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
            {
                countLoop++;
                buf2Buf(gupPriceTermJournalTransEntityTempItem, gupPriceTermJournalTransEntity);
                gupPriceTermJournalTransEntity.Line1 = metInventItemOrderSetupOrigItem.ItemId;
                gupPriceTermJournalTransEntity.ValidFrom = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
                gupPriceTermJournalTransEntity.LineNum = GUPPriceTermJournalTrans::lastLineNum(agreementId) + countLoop;
                gupPriceTermJournalTransEntityRecordInsertList.add(gupPriceTermJournalTransEntity);
            }
            gupPriceTermJournalTransEntityRecordInsertList.insertDatabase();

            gupPriceTermJournalTable.Status = GUPDisabledEnabled::Enabled;
            gupPriceTermJournalTable.update();

        }

    }

/// <summary>
/// Unlink Item Item from Main Item
/// </summary>
private void unlinkTempItem()
{
    metInventItemOrderSetupOrigItem.selectForUpdate(true);
    metInventItemOrderSetupOrigItem.TempItemPackChg = '';
    metInventItemOrderSetupOrigItem.SubrangeId = '';
    metInventItemOrderSetupOrigItem.SubrangeDesc = '';
    metInventItemOrderSetupOrigItem.update();
}

    /// <summary>
    /// Updates the Item Status for given record
    /// </summary>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup table</param>
    /// <param name = "_itemStatus">METItemStatus enum</param>
    /// <param name = "_updateDiscontinued">true or false</param>
    private void updateItemStatus(METInventItemOrderSetup _metInventItemOrderSetup, METItemStatus _itemStatus, boolean _updateDiscontinued = false)
    {
        utcdatetime currentDateTime = DateTimeUtil::getSystemDateTime();
        _metInventItemOrderSetup.selectForUpdate(true);
        _metInventItemOrderSetup.ItemStatus = _itemStatus;

        if (_updateDiscontinued)
        {
            _metInventItemOrderSetup.DiscontinueDate = DateTimeUtil::date(DateTimeUtil::applyTimeZoneOffset(currentDateTime, DateTimeUtil::getUserPreferredTimeZone()));
        }

        _metInventItemOrderSetup.update();
    }

    /// <summary>
    /// Reprice open sales orders
    /// </summary>
    private void rePriceOpenSalesOrders()
    {
        SalesTable salesTable;
        SalesLine salesLine;
        METSalesLine metSalesLine;
        InventDim inventDim;
        EcoResProductUnitConverter productUnitConverter;
        UnitOfMeasure unitOfMeasureFrom;
        UnitOfMeasure unitOfMeasureTo;
        UnitOfMeasureConversion unitOfMeasureConversionDirect;   
        
        InventTable inventTable;
        EcoResProduct ecoResProduct;
        InventTableModule inventTableModuleOldPack;
        real factorA, factorB, convertedValue;

        inventDim.clear();
        inventDim.InventSiteId = metInventItemOrderSetupOrigItem.SiteId;
        inventDim = InventDim::findDim(inventDim);
    
        try
        {
            while select RecId from salesTable
                where salesTable.SalesStatus == SalesStatus::Backorder
                    && salesTable.DocumentStatus == DocumentStatus::Confirmation    
                join forupdate salesLine
                    where salesLine.SalesId == salesTable.SalesId
                    && salesLine.ItemId == metInventItemOrderSetupOrigItem.ItemId
                    && salesLine.SalesStatus == SalesStatus::Backorder
                join RecId, ItemId from inventTable 
                    where InventTable.ItemId == SalesLine.ItemId
                join RecId from ecoResProduct
                    where ecoResProduct.RecId == inventTable.Product
                join RecId from metSalesLine
                    where metSalesLine.SalesLine == salesLine.RecId
                    && metSalesLine.OrderExtractStatus == METOrderExtractStatus::Open
            {
                //Calculate Factor-A - Old unit to Sales Unit
                inventTableModuleOldPack = InventTableModule::find(inventTable.ItemId, ModuleInventPurchSales::Invent);
                unitOfMeasureTo = UnitOfMeasure::findBySymbol(inventTableModuleOldPack.UnitId);
                unitOfMeasureFrom = UnitOfMeasure::findBySymbol(salesLine.SalesUnit);

                productUnitConverter = EcoResProductUnitConverter::newForDistinctProduct(ecoResProduct.RecId, unitOfMeasureFrom.RecId, unitOfMeasureTo.RecId, NoYes::No);

                factorA = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                                inventTable.ItemId,
                                salesLine.InventDimId,
                                salesLine.SalesQty,
                                salesLine.SalesUnit,
                                inventTableModuleOldPack.UnitId,
                                NoYes::Yes);

                //Calculate Factor-B 
                select firstonly Product
                    from inventTable
                    where inventTable.ItemId == metInventItemOrderSetupTempItem.ItemId;
                   
                unitOfMeasureFrom = UnitOfMeasure::findBySymbol(inventTable.inventItemSalesSetup(inventDim.inventdimId).METSalesUnit);

                productUnitConverter = EcoResProductUnitConverter::newForDistinctProduct(inventTable.Product, unitOfMeasureFrom.RecId, unitOfMeasureTo.RecId, NoYes::No);
                
                factorB = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                                inventTable.ItemId,
                                salesLine.InventDimId,
                                salesLine.SalesQty,
                                inventTable.inventItemSalesSetup(inventDim.inventdimId).METSalesUnit,
                                inventTableModuleOldPack.UnitId,
                                NoYes::Yes);             
                
                if (factorB != 0)
                { 
                    ttsbegin;
                    unitOfMeasureConversionDirect = UnitOfMeasureConversion::findByConversion(unitOfMeasureTo.RecId, unitOfMeasureFrom.RecId);
                    convertedValue = this.roundValue(factorA / factorB, unitOfMeasureTo, unitOfMeasureConversionDirect.Rounding);
                    salesLine.SalesUnit = unitOfMeasureFrom.Symbol;
                    salesline.SalesQty = convertedValue;
                    salesLine.update();
                    ttscommit;
                }                
            }
        }
        catch(Exception::Error)
        {
            throw Error("@SYS65081");
        }
    }

    /// <summary>
    /// Process NDC dependent sites
    /// </summary>
    private void processNDCDependentSites()
    {
        ReqItemTable reqItemTable;
        InventLocation inventLocation;
        InventSite inventSite;
        METReqItemTableInventDimView metReqItemTableInventDimView;

        while select metReqItemTableInventDimView
            where metReqItemTableInventDimView.ItemId == metInventItemOrderSetupOrigItem.ItemId
            && metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer
            join RecId from inventLocation
            where inventLocation.InventLocationId == metReqItemTableInventDimView.InventLocationIdReqMain
            && inventLocation.METNDCWarehouse == NoYes::Yes
            && inventLocation.InventSiteId == metInventItemOrderSetupOrigItem.SiteId
            join inventSite
            where inventSite.SiteId == metReqItemTableInventDimView.InventSiteId
            && inventSite.METNDCSite == NoYes::Yes
        {
            ItemId mainItem = metInventItemOrderSetupOrigItem.ItemId;
            ItemId tmpItem = METInventItemOrderSetup::findByItemAndSite(metInventItemOrderSetupOrigItem.ItemId, metReqItemTableInventDimView.InventSiteId).TempItemPackChg;

            if (tmpItem)
            {  

                METItemPackChangeHelper metItemPackChangeHelperDependentSites = new METItemPackChangeHelper();

                metItemPackChangeHelperDependentSites.parmMETInventItemOrderSetup(METInventItemOrderSetup::findByItemAndSite(mainItem, metReqItemTableInventDimView.InventSiteId));
                metItemPackChangeHelperDependentSites.parmMETInventItemOrderSetupTempItem(METInventItemOrderSetup::findByItemAndSite(tmpItem, metReqItemTableInventDimView.InventSiteId));

                metItemPackChangeHelperDependentSites.parmInventItemPurchSetupOrigItem(InventItemPurchSetup::find(metInventItemOrderSetupOrigItem.ItemId, metReqItemTableInventDimView.CovInventDimId));
                metItemPackChangeHelperDependentSites.parmInventItemPurchSetupTempItem(InventItemPurchSetup::find(tmpItem, metReqItemTableInventDimView.CovInventDimId));

                metItemPackChangeHelperDependentSites.parmInventItemSalesSetupOrigItem(InventItemSalesSetup::find(metInventItemOrderSetupOrigItem.ItemId, metReqItemTableInventDimView.CovInventDimId));
                metItemPackChangeHelperDependentSites.parmInventItemSalesSetupTempItem(InventItemSalesSetup::find(tmpItem, metReqItemTableInventDimView.CovInventDimId));

                metItemPackChangeHelperDependentSites.parmWHSPhysDimUOMOrigItem(METItemPackChangeHelper::getWhsPhysDimOUM(metInventItemOrderSetupOrigItem.ItemId));
                metItemPackChangeHelperDependentSites.parmWHSPhysDimUOMTempItem(METItemPackChangeHelper::getWhsPhysDimOUM(tmpItem));

                metItemPackChangeHelperDependentSites.startOperation_DependentSites();

                //Task110346_CB409-D365ToPIM-child site been added to list- start
                siteList.addEnd(metReqItemTableInventDimView.InventSiteId);
                //Task110346_CB409-D365ToPIM-child site been added to list- end
                
            }
        }
    }

    /// <summary>
    /// Process CDS Dependent Sites
    /// </summary>
    private void processCDSDependentSites()
    {       
        InventLocation inventLocation;
        InventSiteId siteId = metInventItemOrderSetupOrigItem.SiteId;
        METReqItemTableInventDimView metReqItemTableInventDimView;
        
        while select metReqItemTableInventDimView
            where metReqItemTableInventDimView.ItemId == metInventItemOrderSetupOrigItem.ItemId
            && metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer
            join RecId from inventLocation
            where inventLocation.InventLocationId == metReqItemTableInventDimView.InventLocationId
            && inventLocation.METCSDWarehouse == NoYes::Yes
            && metReqItemTableInventDimView.MainWarehouseInventSiteId == siteId
        {
            ItemId mainItem = metInventItemOrderSetupOrigItem.ItemId;
            ItemId tmpItem = METInventItemOrderSetup::findByItemAndSite(metInventItemOrderSetupOrigItem.ItemId, metReqItemTableInventDimView.InventSiteId).TempItemPackChg;

            if (tmpItem)
            {
                METItemPackChangeHelper metItemPackChangeHelperDependentSites = new METItemPackChangeHelper();

                metItemPackChangeHelperDependentSites.parmMETInventItemOrderSetup(METInventItemOrderSetup::findByItemAndSite(mainItem, metReqItemTableInventDimView.InventSiteId));
                metItemPackChangeHelperDependentSites.parmMETInventItemOrderSetupTempItem(METInventItemOrderSetup::findByItemAndSite(tmpItem, metReqItemTableInventDimView.InventSiteId));

                metItemPackChangeHelperDependentSites.parmInventItemPurchSetupOrigItem(InventItemPurchSetup::find(mainItem, metReqItemTableInventDimView.CovInventDimId));
                metItemPackChangeHelperDependentSites.parmInventItemPurchSetupTempItem(InventItemPurchSetup::find(tmpItem, metReqItemTableInventDimView.CovInventDimId));

                metItemPackChangeHelperDependentSites.parmInventItemSalesSetupOrigItem(InventItemSalesSetup::find(mainItem, metReqItemTableInventDimView.CovInventDimId));
                metItemPackChangeHelperDependentSites.parmInventItemSalesSetupTempItem(InventItemSalesSetup::find(tmpItem, metReqItemTableInventDimView.CovInventDimId));

                metItemPackChangeHelperDependentSites.parmWHSPhysDimUOMOrigItem(METItemPackChangeHelper::getWhsPhysDimOUM(mainItem));
                metItemPackChangeHelperDependentSites.parmWHSPhysDimUOMTempItem(METItemPackChangeHelper::getWhsPhysDimOUM(tmpItem));

                metItemPackChangeHelperDependentSites.startOperation_DependentSites();

                //Task110346_CB409-D365ToPIM-child site been added to list- start
                siteList.addEnd(metInventItemOrderSetupOrigItem.SiteId);
                //Task110346_CB409-D365ToPIM-child site been added to list- end
            }
        }
    }

    /// <summary>
    /// Gets the Physical dimensions table buffer
    /// </summary>
    /// <param name = "_itemId">Item Id</param>
    /// <returns>The Physical dimensions table buffer</returns>
    public static WHSPhysDimUOM getWhsPhysDimOUM(ItemId _itemId)
    {
        WHSPhysDimUOM whsPhysDimUOM;
        
        select firstonly whsPhysDimUOM
            where whsPhysDimUOM.itemId == _itemId;

        return whsPhysDimUOM;
    }

    /// <summary>
    /// Gets the Item code table buffer
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <param name = "_inventDim">InventDim</param>
    /// <param name = "_inventUnit">InventUnitId</param>
    /// <returns>ItemBarCode</returns>
    public static ItemBarCode getInventItembarcode(ItemId _itemId, InventDim _inventDim, InventUnitId _inventUnit)
    {
        METReqItemTableInventDimView metReqItemTableInventDimView;
        InventItemBarcode inventItembarcode;

        select firstonly ReqItemTableRecId, VendId, RecId from metReqItemTableInventDimView
            where metReqItemTableInventDimView.ItemId == _itemId
            && metReqItemTableInventDimView.InventSiteId == _inventDim.InventSiteId
            && metReqItemTableInventDimView.VendId != '';

        if (!metReqItemTableInventDimView)
        {
            return '';
        }        
        else if (metReqItemTableInventDimView && metReqItemTableInventDimView.VendId)
        {
            select firstonly itemBarCode from inventItembarcode
                where inventItembarcode.itemId == _itemId
                && inventItembarcode.METDefault == NoYes::Yes
                && inventItembarcode.METVendAccount == metReqItemTableInventDimView.VendId
                && inventItembarcode.UnitID == _inventUnit;
        }

        return inventItembarcode.itemBarCode;
    }

    /// <summary>
    /// Get vendor List price
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <param name = "_inventDim">InventDim</param>
    /// <returns>GUPVendPriceAmount</returns>
    public static GUPVendPriceAmount getVendorListPrice(ItemId _itemId, InventDim _inventDim)
    {
        METReqItemTableInventDimView metReqItemTableInventDimView;
        InventDim       inventDimPrice;
        InventLocation  inventLocation;
        GUPVendPriceAdmTrans gupVendPriceAdmTrans;
        GUPVendPriceAmount amount;
        GUPVendPriceJournalNum journalNum;

        select firstonly RecId, VendId from metReqItemTableInventDimView
            join InventLocationId,METNDCWarehouse from inventLocation
            where inventLocation.InventLocationId == metReqItemTableInventDimView.InventLocationId
            && metReqItemTableInventDimView.InventSiteId == _inventDim.InventSiteId
            && metReqItemTableInventDimView.ItemId == _itemId;

        if (metReqItemTableInventDimView && !inventLocation.METNDCWarehouse)
        {
            journalNum = metReqItemTableInventDimView.VendId + METConstants::hyphen + metReqItemTableInventDimView.InventLocationId;

            select firstonly Amount from gupVendPriceAdmTrans
                order by gupVendPriceAdmTrans.LineNum desc
                where gupVendPriceAdmTrans.JournalNum == journalNum
                && gupVendPriceAdmTrans.ItemNum == _itemId
                exists join inventDimPrice
                where inventDimPrice.inventDimId == gupVendPriceAdmTrans.InventDimId
                && inventDimPrice.InventLocationId == metReqItemTableInventDimView.InventLocationId
                && inventDimPrice.InventSiteId == _inventDim.InventSiteId;

            amount = gupVendPriceAdmTrans.Amount;
            
        } 
        else if(metReqItemTableInventDimView && inventLocation.METNDCWarehouse)
        {
            inventLocation.clear();

            select firstonly RecId, VendId from metReqItemTableInventDimView
                where metReqItemTableInventDimView.InventSiteId == _inventDim.InventSiteId
                && metReqItemTableInventDimView.ItemId == _itemId
                join RecId, InventLocationId from inventLocation
                where inventLocation.InventLocationId == metReqItemTableInventDimView.InventLocationId
                && inventLocation.METNDCWarehouse == NoYes::Yes
                && metReqItemTableInventDimView.ReqPOType == ReqPOType::Purch;

            journalNum = metReqItemTableInventDimView.VendId +  METConstants::hyphen + inventLocation.InventLocationId;
        
            select firstonly Amount from gupVendPriceAdmTrans
                order by gupVendPriceAdmTrans.LineNum desc
                where gupVendPriceAdmTrans.JournalNum == journalNum
                && gupVendPriceAdmTrans.ItemNum == _itemId
                exists join inventDimPrice
                where inventDimPrice.inventDimId == gupVendPriceAdmTrans.InventDimId
                && inventDimPrice.InventLocationId == inventLocation.InventLocationId
                && inventDimPrice.InventSiteId == _inventDim.InventSiteId;

            amount = gupVendPriceAdmTrans.Amount;

        }        
        
        return amount;
        
    }

/// <summary>
/// Gets the Item site settings buffer
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <param name = "_inventSiteId">Site id</param>
/// <returns>The Item site settings buffer</returns>
public static METInventItemOrderSetup getItemSiteSettingsSetup(ItemId _itemId, InventSiteId _inventSiteId)
{
    return METInventItemOrderSetup::findByItemAndSite(_itemId, _inventSiteId); 
}

    /// <summary>
    /// Round the value using unit conversion rounding rules
    /// </summary>
    /// <param name = "_value">Value to round</param>
    /// <param name = "_toUnit">To unit</param>
    /// <param name = "_rounding">Round method</param>
    /// <returns>round value</returns>
    private real roundValue(real _value, UnitOfMeasure _toUnit, UnitOfMeasureConversionRounding _rounding)
    {
        real    ret;
        int     sign    = 1;
        
        switch (_rounding)
        {
            case UnitOfMeasureConversionRounding::Nearest   :
                ret = decRound(sign * _value, this.roundingDecimalPrecision(_toUnit.RecId));
                break;

            case UnitOfMeasureConversionRounding::Up        :
                ret = roundUpDec(sign * _value, this.roundingDecimalPrecision(_toUnit.RecId));
                break;

            case UnitOfMeasureConversionRounding::Down      :
                ret = roundDownDec(sign * _value, this.roundingDecimalPrecision(_toUnit.RecId));
                break;
        }

        return sign * ret;
    }

    /// <summary>
    /// Rounds the value down
    /// </summary>
    /// <param name = "value">Value to round</param>
    /// <param name = "numDec">Number of decimals</param>
    /// <returns>real</returns>
    static real roundDownDec(real value, int numDec)
    {
        real unit   = 1;
        int num     = numDec;
        while (num > 0)
        {
            unit        = unit/10;
            num         = num-1;
        }

        return roundDown(value, unit);
    }

    /// <summary>
    /// Rounds the value up
    /// </summary>
    /// <param name = "value">Value to round</param>
    /// <param name = "unit">Rounding unit</param>
    /// <returns>real</returns>
    static real roundUp(real value, real unit)
    {
        real    roundedValue;

        roundedValue = round(value,unit);
        // Check for special case
        if (value== roundedValue)
        {
            return value;
        }
        // for numerical reasons we subtract the major part of the number before rounding
        return round(value - roundedValue + unit/2, unit) + roundedValue;
        
    }

    /// <summary>
    /// Round up to decimal
    /// </summary>
    /// <param name = "value">Value to round</param>
    /// <param name = "numDec">Number of decimals</param>
    /// <returns>real</returns>
    static real roundUpDec(real value, int numDec)
    {
        real unit = 1;
        int num     = numDec;
        while (num > 0)
        {
            unit        = unit/10;
            num         = num-1;
        }

        return roundUp(value,unit);
    }

/// <summary>
/// The rounding decimal precision
/// </summary>
/// <param name = "_toUnit">To unit</param>
/// <returns>Precision value</returns>
private UnitOfMeasureDecimalPrecision roundingDecimalPrecision(RecId _toUnit)
{
    return  UnitOfMeasure::find(_toUnit).DecimalPrecision;
}

    /// <summary>
    /// Run vendor change request
    /// </summary>
    private void runVendorChangeRequest()
    {
        METReqItemTable metReqItemTable;
        METReqItemTableInventDimView metReqItemTableInventDimView;

        while select ItemId, CovInventDimId, ReqPOType, InventLocationIdReqMain, VendId, InventSiteId
            from metReqItemTableInventDimView
            exists join metReqItemTable
            where metReqItemTable.RefRecId == metReqItemTableInventDimView.ReqItemTableRecId
            && metReqItemTable.PendingVendChangeDate <= DateTimeUtil::getSystemDateTime()
            && metReqItemTable.PendingVendAccountNumber != ''
            && metReqItemTableInventDimView.ItemId == metInventItemOrderSetupOrigItem.ItemId
            && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetupOrigItem.SiteId
        {
            METVendorChangeRequestController    controller  = METVendorChangeRequestController::construct();
            METVendorChangeRequestContract      contract    = controller ? controller.getDataContractObject() : null;

            if (!contract)
            {
                throw error(Error::wrongUseOfFunction(funcName()));
            }

            // Set contract fields
            contract.parmItemId(metReqItemTableInventDimView.ItemId);
            contract.parmInventSiteId(metReqItemTableInventDimView.InventSiteId);
            contract.parmCalledFromDefaultForm(true);

            controller.parmExecutionMode(SysOperationExecutionMode::ScheduledBatch); // Set execution mode
            controller.parmShowDialog(false); // Prevent dialog
            controller.parmLoadFromSysLastValue(false); // Prevent loading from last value
            controller.parmInBatch(true);
            controller.parmDialogCaption(strFmt("@MET:VendChangeReqBatch @DOMLabels:DOMItemId - %1 @SYS177684 - %2",metInventItemOrderSetupOrigItem.ItemId, metInventItemOrderSetupOrigItem.SiteId));
            // Start operation
            controller.startOperation();
        }
    }

///Task110346_CB409-D365ToPIM
/// <summary>
/// trigger the item pack change business event on completion
/// </summary>
/// <param name = "_itemId">Itemid</param>
/// <param name = "_tempItemPackChg">Temp item</param>
/// <param name = "_inventSiteId">InventSite list</param>
private void triggerItemPackchangeCompleteBusinessEvent(ItemId _itemId, METTempItemPackChg _tempItemPackChg, list _inventSiteId)
{
    if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METItemPackChangeCompletedBusinessEvent)))
    {
        METItemPackChangeCompletedBusinessEvent::newFromItemPackChangeCompleted(_itemId, _tempItemPackChg, _inventSiteId).send();
    }
}
